-- 0548: release 28's words in the Academy and the guides (docs/changes/2026-11-07-r28-operations.md).
--   The Academy (Admin > Academy), as shipped by 0208: an offer holds the car once the renter approves it (0540), the
--   first to approve gets it; deposits stay holds (0541). Copy an Admin changed is left as it is (each update matches the
--   text as it was shipped).
--   The guide chapters release 28 changed, published as 0059 does (an Admin's earlier text stays in the history).
-- No applied migration is edited.

update academy_lessons set scenes = replace(replace(scenes::text,
    'It does not hold the car: the first renter to pay gets it. If someone else pays first, the renter sees \"This car was just taken\" and their authorization is released.',
    'It holds the car once the renter approves it: the first renter to approve gets the car, even before paying. Any other offer on the same car and dates comes back to us to re-offer.'),
    '"First to pay gets the car"', '"First to approve gets the car"')::jsonb
 where scenes::text like '%the first renter to pay gets it%';
update academy_lessons set scenes = replace(scenes::text,
    'The deposit is refundable. It is a hold on the renter''s card on file, taken about an hour before pickup, not when they pay for the booking.',
    'The deposit is refundable. It is a hold on the renter''s card on file, taken on the pickup day, not when they pay for the booking. It stays a hold with Stripe for any length of rental, renewed before it lapses, and is never captured except for what is owed.')::jsonb
 where scenes::text like '%It is a hold on the renter''s card on file, taken about an hour before pickup%';
update academy_questions
   set prompt = 'Two renters have offers for the same car and dates. One approves first; the other has not answered. What happens?',
       options = '["The first renter keeps the car for 24 hours", "The car goes to the renter who approved first; the other offer comes back to staff", "Both bookings are confirmed", "Staff must choose"]'::jsonb,
       answer = 1,
       explain = 'Approving books the car: the first renter to approve gets it, even before paying. Payment due is a badge and a To do, never the reason a booking is not booked.'
 where prompt = 'A renter has an open offer but has not paid. Another renter pays first for the same car. What happens?';

